import {decide,audit} from './engine.mjs';
import {runChecks} from './checks.mjs';
const $=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,result;
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){result=decide(data,$('model').value,$('sku').value,$('region').value);const sources=data.sources.filter(s=>result.sourceIds.includes(s.id));$('result').dataset.status=result.status;$('result').innerHTML=`<h3>${escape(result.title)}</h3><p>${escape(result.detail)}</p>${sources.length?`<ul>${sources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)}</a> · ${escape(s.locator)}</li>`).join('')}</ul>`:''}<p><small>Scope: genuine Winix filters · US documentation · reviewed ${data.reviewedAt}</small></p>`;$('reply').textContent=audit(data,result).customerReply;$('notice').textContent='';}
async function init(){try{const r=await fetch('./data.json');if(!r.ok)throw Error('Source register unavailable');data=await r.json();$('models').innerHTML=[...new Set(data.sources.flatMap(s=>s.models))].sort().map(m=>`<option value="${escape(m)}"></option>`).join('');$('matrix').innerHTML=data.products.map(p=>{const s=data.sources.find(s=>s.sku===p.sku&&s.type==='Manufacturer product page');return `<tr><td>${p.name}<br><small>${p.sku}</small></td><td>${s.models.join(', ')}</td><td><a href="${s.url}" target="_blank" rel="noopener noreferrer">Product page</a><br><small>${s.locator}</small></td><td>${s.reviewedAt}</td></tr>`}).join('');$('sources').innerHTML=data.sources.map(s=>`<article class="source"><span class="eyebrow">${s.id} / ${s.type}</span><b><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title}</a></b><p>${s.locator}</p><p>Revision: ${s.revision}</p><p>${s.access} · ${s.reviewedAt}</p>${s.lastRetrievalAttempt?`<p>Latest retrieval: ${escape(s.lastRetrievalAttempt.date)} · ${escape(s.lastRetrievalAttempt.outcome)}</p>`:""}</article>`).join('');$('form').addEventListener('submit',e=>{e.preventDefault();render()});document.querySelectorAll('[data-model]').forEach(b=>b.addEventListener('click',()=>{$('model').value=b.dataset.model;$('sku').value=b.dataset.sku;$('region').value='US';render();$('model').focus()}));$('download').addEventListener('click',()=>{render();download('fit-before-buy-audit.json',JSON.stringify(audit(data,result),null,2))});$('export').addEventListener('click',()=>download('fit-before-buy-source-register.json',JSON.stringify(data,null,2)));$('copy').addEventListener('click',async()=>{render();try{await navigator.clipboard.writeText(audit(data,result).customerReply);$('notice').textContent='Reply copied.'}catch{$('notice').textContent='Copy unavailable. Download the audit to retrieve the reply.'}});$('run').addEventListener('click',()=>{const checks=runChecks(data);$('checks').innerHTML=`<b>${checks.filter(c=>c.passed).length}/${checks.length} decision checks passed · October 7 snapshot</b><ul>${checks.map(c=>`<li class="${c.passed?'pass':'fail'}">${c.passed?'PASS':'FAIL'} · ${escape(c.name)}</li>`).join('')}</ul><p>Decision rules and dataset consistency checks; not physical tests or independent proof of every source claim.</p>`});render();}catch(e){$('result').dataset.status='unknown';$('result').innerHTML='<h3>Evidence could not load</h3><p>The checker cannot issue a match without its source register. Please reload.</p>';$('reply').textContent='No reply is available until the evidence loads.';for(const id of ['download','copy','run','export'])$(id).disabled=true;}}init();
